#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    unordered_map<long long, int> count;
    for (int i = 0; i < n; i++) count[a[i]]++;
    long long repeated = 0, missing = 0;
    for (long long v = 1; v <= n; v++) {
        int c = count.count(v) ? count[v] : 0;
        if (c == 2) repeated = v;
        else if (c == 0) missing = v;
    }
    cout << repeated << " " << missing << "\n";

    return 0;
}

code.java:
import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        Map<Long, Integer> count = new HashMap<>();
        for (int i = 0; i < n; i++) count.merge(a[i], 1, Integer::sum);
        long repeated = 0, missing = 0;
        for (long v = 1; v <= n; v++) {
            int c = count.getOrDefault(v, 0);
            if (c == 2) repeated = v;
            else if (c == 0) missing = v;
        }
        System.out.println(repeated + " " + missing);
    }
}
